{
  "name": "Coherent Sapphire 激光器",
  "name_en": "Coherent Sapphire Laser",
  "manufacturer": "Coherent",
  "description": "这是一台 Coherent Sapphire 系列激光器，用于提供稳定的连续激光输出。此类激光器常用于显微成像、荧光激发、光路校准和其他需要稳定光源的实验场景，并支持功率开关与输出功率调节。",
  "description_en": "This is a Coherent Sapphire series laser that provides stable continuous laser output. Such lasers are commonly used for microscopy, fluorescence excitation, optical alignment, and other laboratory applications requiring a stable light source, with support for laser on/off control and power adjustment.",
  "tag_hints": [
    "continuous-wave laser",
    "solid-state laser",
    "laser power control",
    "fluorescence excitation",
    "microscopy illumination",
    "optical alignment"
  ],
  "actions": [
    {
      "action_name": "auto-query",
      "description": "发送设备命令并读取激光器返回信息。",
      "description_en": "Send a device command and read the laser's reply."
    },
    {
      "action_name": "auto-IsOn",
      "description": "获取激光器的开关状态。",
      "description_en": "Get the laser on/off state."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "开启激光输出。",
      "description_en": "Turn on the laser output."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光输出。",
      "description_en": "Turn off the laser output."
    },
    {
      "action_name": "auto-check_set_power",
      "description": "读取当前设定的激光功率值。",
      "description_en": "Read the current configured laser power setting."
    },
    {
      "action_name": "auto-check_power_output",
      "description": "读取当前激光输出功率。",
      "description_en": "Read the current laser output power."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置激光功率。",
      "description_en": "Set the laser power."
    },
    {
      "action_name": "auto-GetMAX",
      "description": "获取可设置的最大激光功率。",
      "description_en": "Get the maximum configurable laser power."
    },
    {
      "action_name": "auto-GetMIN",
      "description": "获取可设置的最小激光功率。",
      "description_en": "Get the minimum configurable laser power."
    },
    {
      "action_name": "auto-GetPower",
      "description": "获取当前激光功率设定值。",
      "description_en": "Get the current laser power setpoint."
    },
    {
      "action_name": "auto-Close",
      "description": "关闭与激光器的通信连接。",
      "description_en": "Close the communication connection to the laser."
    }
  ]
}

